  let bodyIndex = data.search(/\n\s*\r?\n/);
  if (bodyIndex < 0) {
    bodyIndex = 0;
  } else {
    const wsSize = data.match(/\n\s*\r?\n/);
    bodyIndex += wsSize[0].length;
  }

  if (data.substr(bodyIndex).search(/\r?\n$/) === 0) {
    return;
